package com.hashem.sms;
import android.content.*;import android.database.sqlite.*;import android.database.*;import android.net.Uri;import android.provider.Telephony;import java.util.*;
public class Db extends SQLiteOpenHelper{
 public Db(Context c){super(c,"hashem.db",null,3);} 
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE messages(id INTEGER PRIMARY KEY AUTOINCREMENT,address TEXT,body TEXT,type TEXT,status TEXT,ts INTEGER,thread INTEGER,read INTEGER DEFAULT 0,star INTEGER DEFAULT 0)");d.execSQL("CREATE TABLE groups(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE)");d.execSQL("CREATE TABLE group_members(gid INTEGER,address TEXT,name TEXT,PRIMARY KEY(gid,address))");d.execSQL("CREATE TABLE schedules(id INTEGER PRIMARY KEY AUTOINCREMENT,address TEXT,body TEXT,at INTEGER)");}
 public void onUpgrade(SQLiteDatabase d,int a,int b){if(a<2){d.execSQL("ALTER TABLE messages ADD COLUMN star INTEGER DEFAULT 0");}if(a<3){d.execSQL("CREATE TABLE IF NOT EXISTS forward_rules(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,destination TEXT NOT NULL)");}}
 public long addMessage(String a,String b,String t,String s){ContentValues v=cv(a,b,t,s);return getWritableDatabase().insert("messages",null,v);}
 public void status(long id,String s){ContentValues v=new ContentValues();v.put("status",s);getWritableDatabase().update("messages",v,"id=?",new String[]{""+id});}
 public void saveOutgoingToSystemProvider(Context context,long id){Cursor c=getReadableDatabase().query("messages",new String[]{"address","body","ts"},"id=?",new String[]{String.valueOf(id)},null,null,null);try{if(!c.moveToFirst())return;ContentValues v=new ContentValues();v.put(Telephony.Sms.ADDRESS,c.getString(0));v.put(Telephony.Sms.BODY,c.getString(1));v.put(Telephony.Sms.DATE,c.getLong(2));v.put(Telephony.Sms.READ,1);v.put(Telephony.Sms.SEEN,1);v.put(Telephony.Sms.TYPE,Telephony.Sms.MESSAGE_TYPE_OUTBOX);Uri uri=context.getContentResolver().insert(Telephony.Sms.CONTENT_URI,v);if(uri!=null){long providerId=Long.parseLong(uri.getLastPathSegment());ContentValues local=new ContentValues();local.put("thread",providerId);getWritableDatabase().update("messages",local,"id=?",new String[]{String.valueOf(id)});}}catch(Exception ignored){}finally{c.close();}}
 public void updateSystemProviderStatus(Context context,long id,boolean success){Cursor c=getReadableDatabase().query("messages",new String[]{"thread"},"id=?",new String[]{String.valueOf(id)},null,null,null);try{if(!c.moveToFirst())return;long providerId=c.getLong(0);if(providerId<=0)return;ContentValues v=new ContentValues();v.put(Telephony.Sms.TYPE,success?Telephony.Sms.MESSAGE_TYPE_SENT:Telephony.Sms.MESSAGE_TYPE_FAILED);context.getContentResolver().update(Uri.parse("content://sms/"+providerId),v,null,null);}catch(Exception ignored){}finally{c.close();}}
 private ContentValues cv(String a,String b,String t,String s){ContentValues v=new ContentValues();v.put("address",a);v.put("body",b);v.put("type",t);v.put("status",s);v.put("ts",System.currentTimeMillis());return v;}
 public Cursor list(String filter){String w="";if("unread".equals(filter))w=" WHERE read=0";else if("failed".equals(filter))w=" WHERE status='failed' OR status='لم يتم الإرسال'";else if("archived".equals(filter))w=" WHERE type='archived'";else if("blocked".equals(filter))w=" WHERE type='blocked'";else if("trash".equals(filter))w=" WHERE type='trash'";return getReadableDatabase().rawQuery("SELECT * FROM messages"+w+" ORDER BY ts DESC",null);}
 public Cursor listThreads(String filter){String condition="";if("unread".equals(filter))condition=" AND EXISTS (SELECT 1 FROM messages u WHERE u.address=m.address AND u.type='in' AND u.read=0 AND u.type!='trash')";else if("archived".equals(filter))condition=" AND EXISTS (SELECT 1 FROM messages a WHERE a.address=m.address AND a.type='archived')";else if("blocked".equals(filter))condition=" AND EXISTS (SELECT 1 FROM messages b WHERE b.address=m.address AND b.type='blocked')";else if("trash".equals(filter))condition=" AND NOT EXISTS (SELECT 1 FROM messages z WHERE z.address=m.address AND z.type!='trash')";return getReadableDatabase().rawQuery("SELECT m.* FROM messages m INNER JOIN (SELECT address,MAX(ts) latest FROM messages WHERE type!='trash' GROUP BY address) t ON m.address=t.address AND m.ts=t.latest WHERE m.type!='trash'"+condition+" ORDER BY m.ts DESC",null);}
 public void markThreadRead(String address){ContentValues v=new ContentValues();v.put("read",1);getWritableDatabase().update("messages",v,"address=? AND type='in'",new String[]{address});}
 public void linkProviderMessage(long localId,long providerId){ContentValues v=new ContentValues();v.put("thread",providerId);getWritableDatabase().update("messages",v,"id=?",new String[]{String.valueOf(localId)});}
 public void importSystemMessage(long providerId,String address,String body,int providerType,long date,int isRead){if(address==null||body==null||providerId<=0)return;Cursor existing=getReadableDatabase().query("messages",new String[]{"id"},"thread=?",new String[]{String.valueOf(providerId)},null,null,null);boolean found=existing.moveToFirst();existing.close();if(found)return;String type=providerType==Telephony.Sms.MESSAGE_TYPE_INBOX?"in":"out";String status=providerType==Telephony.Sms.MESSAGE_TYPE_SENT?"تم الإرسال":providerType==Telephony.Sms.MESSAGE_TYPE_FAILED?"لم يتم الإرسال":providerType==Telephony.Sms.MESSAGE_TYPE_OUTBOX?"جارٍ الإرسال":"received";ContentValues v=cv(address,body,type,status);v.put("thread",providerId);v.put("ts",date);v.put("read",isRead);getWritableDatabase().insert("messages",null,v);}
 public long createGroup(String name){ContentValues v=new ContentValues();v.put("name",name.trim());return getWritableDatabase().insert("groups",null,v);}
 public void addGroupMember(long gid,String address,String name){ContentValues v=new ContentValues();v.put("gid",gid);v.put("address",address.trim());v.put("name",name==null?"":name.trim());getWritableDatabase().insertWithOnConflict("group_members",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 public Cursor listGroups(){return getReadableDatabase().query("groups",new String[]{"id","name"},null,null,null,null,"name COLLATE NOCASE ASC");}
 public Cursor groupMembers(long gid){return getReadableDatabase().query("group_members",new String[]{"address","name"},"gid=?",new String[]{String.valueOf(gid)},null,null,"name COLLATE NOCASE ASC");}
 public Cursor thread(String address){return getReadableDatabase().query("messages",null,"address=? AND type!='trash'",new String[]{address},null,null,"ts ASC");}
 public Cursor messagesByIds(ArrayList<Long> ids){if(ids.isEmpty())return getReadableDatabase().rawQuery("SELECT * FROM messages WHERE 1=0",null);StringBuilder q=new StringBuilder();String[] a=new String[ids.size()];for(int i=0;i<ids.size();i++){if(i>0)q.append(',');q.append('?');a[i]=String.valueOf(ids.get(i));}return getReadableDatabase().rawQuery("SELECT * FROM messages WHERE id IN ("+q+") ORDER BY ts ASC",a);}
 public void deleteMessages(ArrayList<Long> ids){if(ids.isEmpty())return;StringBuilder q=new StringBuilder();String[] a=new String[ids.size()];for(int i=0;i<ids.size();i++){if(i>0)q.append(',');q.append('?');a[i]=String.valueOf(ids.get(i));}ContentValues v=new ContentValues();v.put("type","trash");getWritableDatabase().update("messages",v,"id IN ("+q+")",a);}
 public void starMessages(ArrayList<Long> ids){if(ids.isEmpty())return;StringBuilder q=new StringBuilder();String[] a=new String[ids.size()];for(int i=0;i<ids.size();i++){if(i>0)q.append(',');q.append('?');a[i]=String.valueOf(ids.get(i));}getWritableDatabase().execSQL("UPDATE messages SET star=CASE WHEN star=1 THEN 0 ELSE 1 END WHERE id IN ("+q+")",a);}
 public void deleteThread(String address){ContentValues v=new ContentValues();v.put("type","trash");getWritableDatabase().update("messages",v,"address=?",new String[]{address});}
 public long createForwardRule(String name,String destination){ContentValues v=new ContentValues();v.put("name",name.trim());v.put("destination",destination.trim());return getWritableDatabase().insertWithOnConflict("forward_rules",null,v,SQLiteDatabase.CONFLICT_IGNORE);}
 public Cursor listForwardRules(){return getReadableDatabase().query("forward_rules",new String[]{"id","name","destination"},null,null,null,null,"name COLLATE NOCASE ASC");}
 public void deleteForwardRule(long id){getWritableDatabase().delete("forward_rules","id=?",new String[]{String.valueOf(id)});}
}
